    87  static int32_t
    88  debug_get_line(mrb_state *mrb, mrb_irep_debug_info_file* f, uint32_t pc)
    89  {
    90    if (f == NULL) return -1;
    91    switch (f->line_type) {
    92    case mrb_debug_line_ary:
    93      mrb_assert(f->start_pos <= pc && pc < (f->start_pos + f->line_entry_count));
    94      return f->lines.ary[pc - f->start_pos];
    95
    96    case mrb_debug_line_flat_map:
    97      {
    98        /* get upper bound */
    99        const mrb_irep_debug_info_line *ret = f->lines.flat_map;
   100        uint32_t count = f->line_entry_count;
   101        while (count > 0) {
   102          int32_t step = count / 2;
   103          const mrb_irep_debug_info_line *it = ret + step;
   104          if (!(pc < it->start_pos)) {
   105            ret = it + 1;
   106            count -= step + 1;
   107          }
   108          else { count = step; }
   109        }
   110
   111        --ret;
   112
   113        /* check line entry pointer range */
   114        mrb_assert(f->lines.flat_map <= ret && ret < (f->lines.flat_map + f->line_entry_count));
   115        /* check pc range */
   116        //      mrb_assert(ret->start_pos <= pc &&
   117        //                 pc < (((uint32_t)(ret + 1 - f->lines.flat_map) < f->line_entry_count)
   118        //                       ? (ret+1)->start_pos : irep->debug_info->pc_count));
   119        return ret->line;
   120      }
   121
   122    case mrb_debug_line_packed_map:
   123      {
   124        const uint8_t *p = f->lines.packed_map;
   125        const uint8_t *pend = p + f->line_entry_count;
   126        uint32_t pos = 0, line = 0, line_diff;
   127        while (p < pend) {
   128          pos += mrb_packed_int_decode(p, &p);
   129          line_diff = mrb_packed_int_decode(p, &p);
   130          if (pc < pos) break;
   131          line += line_diff;
   132        }
   133        return line;
   134      }
   135    }
   136    return -1;
   137  }
