   204    mrb_assert(lines);
   205
   206    if (d->flen > 0) {
   207      const char *fn = mrb_sym_name_len(mrb, d->files[d->flen - 1]->filename_sym, NULL);
   208      if (strcmp(filename, fn) == 0)
   209        return NULL;
   210    }
   211
   212    f = (mrb_irep_debug_info_file*)mrb_malloc(mrb, sizeof(*f));
   213    d->files = (mrb_irep_debug_info_file**)mrb_realloc(mrb, d->files, sizeof(mrb_irep_debug_info_file*) * (d->flen + 1));
   214    d->files[d->flen++] = f;
   215
   216    file_pc_count = end_pos - start_pos;
   217
   218    f->start_pos = start_pos;
   219    d->pc_count = end_pos;
   220
   221    fn_len = strlen(filename);
   222    f->filename_sym = mrb_intern(mrb, filename, fn_len);
   223    f->line_type = mrb_debug_line_packed_map;
   224    f->lines.ptr = NULL;
   225
   226    uint16_t prev_line = 0;
   227    uint32_t prev_pc = 0;
   228    size_t packed_size = 0;
   229    uint8_t *p, *pend;
   230
   231    for (i = 0; i < file_pc_count; i++) {
   232      if (lines[start_pos + i] == prev_line) continue;
   233      packed_size += mrb_packed_int_len(start_pos+i-prev_pc);
   234      prev_pc = start_pos+i;
   235      packed_size += mrb_packed_int_len(lines[start_pos+i]-prev_line);
   236      prev_line = lines[start_pos + i];
   237    }
   238    f->lines.packed_map = p = (uint8_t*)mrb_malloc(mrb, packed_size);
   239    pend = p + packed_size;
   240    prev_line = 0; prev_pc = 0;
   241    for (i = 0; i < file_pc_count; i++) {
   242      if (lines[start_pos + i] == prev_line) continue;
   243      p += mrb_packed_int_encode(start_pos+i-prev_pc, p, pend);
   244      prev_pc = start_pos + i;
   245      p += mrb_packed_int_encode(lines[start_pos + i]-prev_line, p, pend);
   246      prev_line = lines[start_pos + i];
   247    }
   248    f->line_entry_count = (uint32_t)packed_size;
   249
   250    return f;
   251  }
